// PlatformActivity 625 activity of an income (same values as the 625 `activities` option). Selects the ISR withholding rate (LIF 2026 art. 25-VI).
type PlatformActivity string

// PmAnnualExtras Informative PM figures. `ptu_base_cents`: 601, ingresos acumulables − deductions (without PTU paid or losses; the art. 28 fr. XXX adjustment is not modelled ⚠️); RESICO PM, utilidad fiscal per art. 212 (⚠️ `resico_pm_ptu_base`). `ptu_to_distribute_cents`: 10 % of the base (601 only, ⚠️ `ptu_rate`; `null` for RESICO PM). `suggested_cu_next_year`: utilidad fiscal ÷ ingresos nominales, 4 decimals half-up (601 only, ⚠️ `cu_rounding`; `"0.0000"` when the utilidad is ≤ 0; `null` for RESICO PM), "Sugerido para tus pagos de {fy+1}".
//
// Examples: {"ptu_base_cents":150000000,"ptu_to_distribute_cents":15000000,"suggested_cu_next_year":"0.1380"}
type PmAnnualExtras struct {
	// PtuBaseCents Signed amount in MXN centavos.
	//
	// Examples: 1250000
	PtuBaseCents         MoneyCents        `json:"ptu_base_cents"`
	PtuToDistributeCents *NonNegativeCents `json:"ptu_to_distribute_cents"`
	SuggestedCuNextYear  *DecimalRate      `json:"suggested_cu_next_year"`
}

// PositiveCents Amount in MXN centavos (>= 1). Same upper bound as `NonNegativeCents`.
//
// Examples: 1000000
type PositiveCents = int64

// RecordDescription Free text, trimmed and NFC-normalized; empty becomes `null`. Never logged (may name a client).
type RecordDescription = string

// RecordsFingerprint SHA-256 (lower-case hex) over the canonical aggregated input, the parameter version and the engine version (ADR-0002 §5). Equal fingerprints mean an identical estimate. M8 stores it with each view only to explain *why* a month changed (`HistoryChangeReason`); the changed marker itself is driven by `FiguresFingerprint`.
//
// Examples: 3f6c2a9e8d7b1c4f5a0e9d8c7b6a5f4e3d2c1b0a9f8e7d6c5b4a3f2e1d0c9b8a
type RecordsFingerprint = string

// RefreshRequest Examples: {"refresh_token":"0199d4a2-7c1e-7b3a-9f10-2c5e8a1b4d01.example-refresh-secret"}
type RefreshRequest struct {
	// RefreshToken The opaque refresh token from `TokenPair`. A malformed value answers `401`, not `400`.
	RefreshToken string `json:"refresh_token"`
}

// Regime Catalog key is `(code, person_type)`; e.g. 626 exists as RESICO PF and RESICO PM. `treatment` is the support level. `incompatible_with` is symmetric (if A lists B, B lists A) and only applies to overlapping period windows; an absent pair is allowed.
//
// Examples: {"code":"626","explanation":null,"incompatible_with":[{"code":"606","reason":"El RESICO cubre los ingresos por arrendamiento (art. 113-E LISR)."},{"code":"612","reason":"El RESICO sustituye al régimen de actividad empresarial y profesional (art. 113-E LISR)."}],"name":"Régimen Simplificado de Confianza","option_defs":[],"person_type":"fisica","required_inputs":[],"treatment":"full"}
type Regime struct {
	// Code SAT c_RegimenFiscal code.
	//
	// Examples: 612
	Code RegimeCode `json:"code"`

	// Explanation Plain-language explanation for a partial or informational regime; `null` for full.
	Explanation      *string                 `json:"explanation"`
	IncompatibleWith []RegimeIncompatibility `json:"incompatible_with"`
	Name             string                  `json:"name"`
	OptionDefs       []RegimeOptionDef       `json:"option_defs"`

	// PersonType Chosen first at onboarding and immutable; fixes the RFC length (13 física, 12 moral).
	PersonType PersonType `json:"person_type"`

	// RequiredInputs Per-fiscal-year tax inputs the estimate needs (`PUT …/tax-inputs`, M5); not options. Exactly the stored `regimes.required_inputs` (CHECK `regime_required_inputs_valid`).
	RequiredInputs []TaxInputDef `json:"required_inputs"`

	// ReviewPendingWith Regimes it may overlap in time, but only with the warning `regime_combination_needs_cpa_review`: the pair is allowed and not yet verified by a CPA (`regime_compatibility.needs_cpa_review`); `reason` is the warning's message. Symmetric, like `incompatible_with`, so the client can warn before submitting. Added in 0.4.0 without a version bump (optional response field); the server always sends it, possibly empty.
	ReviewPendingWith *[]RegimeIncompatibility `json:"review_pending_with,omitempty"`

	// Treatment Support level of a regime: `full` (estimated), `partial` (some taxes only, e.g. IVA) or `informational` (selectable, not estimated; carries an explanation).
	Treatment Treatment `json:"treatment"`
}

// RegimeCode SAT c_RegimenFiscal code.
//
// Examples: 612
type RegimeCode = string

// RegimeEstimate One regime held in the period. `status` precedence: `informational` > `incomplete` > `partial` > `complete`. `complete`: every input this period needs is present. `incomplete`: an input is missing; computed with zero for it, still shown with an "Incompleto" chip and the CTA. `partial`: only some taxes are estimated (621, 622, 603, 625 without the definitive option); `explanation` says what is not. `informational`: no strategy or an informational catalog regime; `explanation` only, `isr` and `iva_components` are `null`. `missing_inputs` is filled whenever inputs are missing, whatever the status. `isr` is `null` when the regime has no ISR figure in the period (informational, partial, an odd month for 621).
//
// Examples: {"cpa_review_pending":false,"cpa_topics":[],"explanation":"Sin el pago definitivo, el ISR se calcula en 612 o RESICO; calcula tu pago ahí y acredita estas retenciones.","isr":null,"iva_components":{"charged_collected_cents":480000,"creditable_paid_cents":0,"definitive_excluded_cents":0,"withheld_from_taxpayer_cents":240000},"missing_inputs":[],"parameter_set":{"fiscal_year":2026,"version":1},"regime_code":"625","regime_name":"Plataformas Tecnológicas","status":"partial","treatment":"full","withheld_to_remit_cents":0}
type RegimeEstimate struct {
	// CpaReviewPending A rule of this regime's computation is not validated by a CPA yet (⚠️ on its lines).
	CpaReviewPending bool       `json:"cpa_review_pending"`
	CpaTopics        []CpaTopic `json:"cpa_topics"`

	// Explanation Plain-language text for a partial or informational regime (or an odd 621 month); `null` otherwise.
	Explanation   *string        `json:"explanation"`
	Isr           *TaxResult     `json:"isr"`
	IvaComponents *IvaComponents `json:"iva_components"`
	MissingInputs []MissingInput `json:"missing_inputs"`

	// ParameterSet The tax parameter set used (embedded `params/<fiscal_year>/v<version>.yaml`, ADR-0002 §3): the highest published version of the period's fiscal year, or the previous year's with `provisional_parameters`.
	//
	// Examples: {"fiscal_year":2026,"version":1}
	ParameterSet ParameterSetRef `json:"parameter_set"`

	// RegimeCode SAT c_RegimenFiscal code.
	//
	// Examples: 612
	RegimeCode RegimeCode           `json:"regime_code"`
	RegimeName string               `json:"regime_name"`
	Status     RegimeEstimateStatus `json:"status"`

	// Treatment Support level of a regime: `full` (estimated), `partial` (some taxes only, e.g. IVA) or `informational` (selectable, not estimated; carries an explanation).
	Treatment Treatment `json:"treatment"`

	// WithheldToRemitCents Amount in MXN centavos (>= 0).
	//
	// Examples: 1250000
	WithheldToRemitCents NonNegativeCents `json:"withheld_to_remit_cents"`
}

// RegimeEstimateStatus defines model for RegimeEstimate.Status.
type RegimeEstimateStatus string

// RegimeIncompatibility A regime that cannot be held in overlapping periods (`regime_compatibility`).
//
// Examples: {"code":"612","reason":"El RESICO sustituye al régimen de actividad empresarial y profesional (art. 113-E LISR)."}
type RegimeIncompatibility struct {
	// Code SAT c_RegimenFiscal code.
	//
	// Examples: 612
	Code RegimeCode `json:"code"`

	// Reason Plain-language reason shown to the user.
	Reason string `json:"reason"`
}

// RegimeList Examples: {"items":[{"code":"606","explanation":null,"incompatible_with":[{"code":"626","reason":"El RESICO cubre los ingresos por arrendamiento (art. 113-E LISR)."}],"name":"Arrendamiento","option_defs":[{"allowed_values":["blind_35","actual"],"default":"blind_35","key":"deduction_mode","label":"Tipo de deducción","required":true,"type":"enum"}],"person_type":"fisica","required_inputs":[],"treatment":"full"},{"code":"625","explanation":null,"incompatible_with":[],"name":"Régimen de las Actividades Empresariales con ingresos a través de Plataformas Tecnológicas","option_defs":[{"allowed_values":["transport_delivery","lodging","goods_services"],"default":null,"key":"activities","label":"Actividades","required":true,"type":"multi_enum"},{"default":false,"key":"definitive_option","label":"Pago definitivo","required":true,"type":"boolean"},{"default":true,"key":"rfc_given_to_platform","label":"Proporcioné mi RFC a la plataforma","required":true,"type":"boolean"}],"person_type":"fisica","required_inputs":[],"treatment":"full"},{"code":"605","explanation":"Tu patrón retiene y entera el ISR; la app no estima pagos mensuales de este régimen.","incompatible_with":[],"name":"Sueldos y Salarios e Ingresos Asimilados a Salarios","option_defs":[],"person_type":"fisica","required_inputs":[],"treatment":"informational"}]}
type RegimeList struct {
	Items []Regime `json:"items"`
}

// RegimeOptionDef One per-regime option (`regimes.option_defs`, data not code). `enum` takes one of `allowed_values`; `multi_enum` takes a non-empty array of distinct `allowed_values`; `boolean` takes `true`/`false`; `rate` takes a decimal string (`DecimalRate`, 0.16 = 16%) within `[min, max]`; both bounds are always present for `rate` and absent for every other type. An omitted option with a `default` is filled server-side; a `required` option with `default: null` must be sent. The shape is exactly the stored `regimes.option_defs` element (its CHECK `regime_option_defs_valid` enforces it).
//
// Examples: {"allowed_values":["blind_35","actual"],"default":"blind_35","key":"deduction_mode","label":"Tipo de deducción","required":true,"type":"enum"}
type RegimeOptionDef struct {
	// AllowedValues Present for `enum` and `multi_enum`.
	AllowedValues *[]string `json:"allowed_values,omitempty"`

	// Default Default value, or `null` when the option has none.
	Default *any `json:"default,omitempty"`

	// Key Examples: deduction_mode
	Key string `json:"key"`

	// Label Spanish label shown in the options form.
	Label string `json:"label"`

	// Max Inclusive upper bound for `rate`; `null` or absent otherwise.
	Max *DecimalRate `json:"max,omitempty"`

	// Min Inclusive lower bound for `rate`; `null` or absent otherwise.
	Min      *DecimalRate        `json:"min,omitempty"`
	Required bool                `json:"required"`
	Type     RegimeOptionDefType `json:"type"`
}

// RegimeOptionDefType defines model for RegimeOptionDef.Type.
type RegimeOptionDefType string

// RegimeOptions Values keyed by `RegimeOptionDef.key`; validated server-side against the regime's `option_defs` (`unknown_option`, `invalid_option`, `required`).
//
// Examples: {"deduction_mode":"blind_35"}
type RegimeOptions map[string]RegimeOptions_AdditionalProperties

// RegimeOptions0 defines model for RegimeOptions.0.
type RegimeOptions0 = string

// RegimeOptions1 defines model for RegimeOptions.1.
type RegimeOptions1 = bool

// RegimeOptions2 defines model for RegimeOptions.2.
type RegimeOptions2 = []string

// RegimeOptions_AdditionalProperties defines model for RegimeOptions.AdditionalProperties.
type RegimeOptions_AdditionalProperties struct {
	union json.RawMessage
}

